const WebSocket = require('ws');
const fs = require('fs');
const WS_URL = 'ws://127.0.0.1:64003/devtools/page/6EE627C8A2974CA66BE0EF1EAF563705';
const ws = new WebSocket(WS_URL, { perMessageDeflate: false });
let id = 0;
function send(method, params) {
  return new Promise((resolve, reject) => {
    const mid = ++id;
    const timer = setTimeout(() => reject(new Error('timeout ' + method)), 45000);
    const onMsg = (data) => {
      const msg = JSON.parse(data);
      if (msg.id === mid) {
        clearTimeout(timer);
        ws.off('message', onMsg);
        msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
      }
    };
    ws.on('message', onMsg);
    ws.send(JSON.stringify({ id: mid, method, params: params || {} }));
  });
}
ws.on('open', async () => {
  try {
    await send('Page.enable');
    const shot = await send('Page.captureScreenshot', { format: 'png', fromSurface: true });
    fs.writeFileSync('/tmp/dlp_admin_panel.png', Buffer.from(shot.data, 'base64'));
    console.log('saved, bytes=', fs.statSync('/tmp/dlp_admin_panel.png').size);
    process.exit(0);
  } catch (e) {
    console.error('ERR', e.message);
    process.exit(1);
  }
});
ws.on('error', (e) => { console.error('WS ERR', e.message); process.exit(1); });
EOF
